viewof a = Inputs.range(
  [0.01, 3],
  {value: 1, step: 0.001, label: "a"}
)
viewof b = Inputs.range(
  [0.01, 3],
  {value: 1, step: 0.001, label: "b"}
)


















Code
data = Array.from({length: 21}, (_, i) =&gt;
  Array.from({length: 21}, (_, j) =&gt; {
    const x = (i / 5)-1;
    const y = (j / 5)-1;

    return {
      X: x,
      Y: y,
      dX: x * (1 - a * x - y),
      dY: y * (b - x - y),
      hnc: 1-a*x,
      vnc: b-x
    };
  })
).flat()








