data3 = Array.from(range(-1.001, 3.001, 0.001), (x) =&gt; ({X:x, vnc1: (b-x + Math.sqrt((b-x)**2 + 4*h))/2, vnc2: (b-x - Math.sqrt((b-x)**2 + 4*h))/2}))

















