  marks: [
    Plot.line(data2, {x: "X", y: "hnc", stroke: "red", strokeWidth: 2, opacity: 0.5}),
    Plot.line(data3, {x: "X", y: "vnc1", stroke: "green", strokeWidth: 2, opacity: 0.5}),
    Plot.lineX(data3, {x: "X", y: "vnc2", stroke: "green", strokeWidth: 2, opacity: 0.5, curve: "linear"}),
    Plot.line(data2, {x: 0, y: "Y", stroke: "red", strokeWidth: 2,opacity: 0.5}),
    Plot.vector(data2, {
      x: "X",
      y: "Y",
      rotate: ({dX, dY}) =&gt; Math.atan2(dX, dY) * 180 / Math.PI,
      length: ({dX, dY}) =&gt; Math.hypot(dX, dY) &gt; 0 ? 1 : 0,
      stroke: "blue"
    }),
    Plot.dot(get_dots(), {x: "X", y: "Y", fill: "black", r: 3})
  ]
})
